begin;
create table public.climate_criteria_versions (
 version text primary key,
 payload jsonb not null check (jsonb_typeof(payload->'rules')='array' and payload->>'version'=version),
 created_at timestamptz not null default clock_timestamp()
);
alter table public.climate_criteria_versions enable row level security;
alter table public.climate_criteria_versions force row level security;
revoke all on public.climate_criteria_versions from public,anon,authenticated;
create function public.climate_preserve_criteria() returns trigger language plpgsql set search_path='' as $$
begin raise exception 'Los criterios históricos son inmutables. Crear una nueva versión.'; end $$;
revoke all on function public.climate_preserve_criteria() from public,anon,authenticated;
create trigger climate_preserve_criteria before update or delete on public.climate_criteria_versions for each row execute function public.climate_preserve_criteria();
