alter table public.agrochemical_climate_readings add column criteria_version text references public.climate_criteria_versions(version);
create function public.climate_stamp_criteria() returns trigger language plpgsql security definer set search_path='' as $$
begin
 select version into new.criteria_version from public.climate_criteria_versions order by created_at desc,version desc limit 1;
 return new;
end $$;
revoke all on function public.climate_stamp_criteria() from public,anon,authenticated;
create trigger climate_stamp_criteria before insert on public.agrochemical_climate_readings for each row execute function public.climate_stamp_criteria();

create function public.climate_dashboard(p_from date,p_to date) returns jsonb language plpgsql security definer set search_path='' as $$
declare profile public.web_profiles; result jsonb;
begin
 profile:=public.web_require_access(false);
 if p_from is null or p_to is null or not isfinite(p_from) or not isfinite(p_to) or p_to<p_from or p_to-p_from>366 then raise exception 'Periodo inválido' using errcode='22023'; end if;
 select jsonb_build_object(
 'can_record',profile.role in ('ADMIN','MANAGER'),
 'current_version',(select version from public.climate_criteria_versions order by created_at desc,version desc limit 1),
 'criteria',(select coalesce(jsonb_agg(payload order by created_at),'[]') from public.climate_criteria_versions),
 'readings',(select coalesce(jsonb_agg(to_jsonb(r) order by r.measured_at,r.id),'[]') from public.agrochemical_climate_readings r where reading_date between p_from and p_to)
 ) into result;
 return result;
end $$;

create function public.climate_web_record_reading(p_id uuid,p_period text,p_temperature_c numeric,p_humidity_percent numeric,p_measured_at timestamptz,p_notes text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare actor public.web_profiles; prior public.agrochemical_climate_readings; day date;
begin
 actor:=public.web_require_access(true);
 if p_id is null or p_period is null or p_period not in ('AM','PM')
 or p_temperature_c is null or not (p_temperature_c between -50 and 100)
 or p_humidity_percent is null or not (p_humidity_percent between 0 and 100)
 or p_measured_at is null or not isfinite(p_measured_at) or p_measured_at>now()
 or p_notes is null or length(p_notes)>1000 then raise exception 'Medición inválida' using errcode='22023'; end if;
 day:=(p_measured_at at time zone 'America/Bogota')::date;
 perform pg_advisory_xact_lock(hashtextextended('climate:'||p_id,0));
 select * into prior from public.agrochemical_climate_readings where id=p_id;
 if found then
   if prior.created_by<>auth.uid() or prior.period<>p_period or prior.temperature_c<>p_temperature_c
   or prior.humidity_percent<>p_humidity_percent or prior.measured_at<>p_measured_at or prior.notes<>p_notes
   then raise exception 'Identificador ya utilizado para otra medición' using errcode='22023'; end if;
   return jsonb_build_object('id',prior.id,'status','confirmed');
 end if;
 perform pg_advisory_xact_lock(hashtextextended('climate-day:'||day||':'||p_period,0));
 if exists(select 1 from public.agrochemical_climate_readings where reading_date=day and period=p_period)
 then raise exception 'Ya existe una medición para esta fecha y turno. Actualiza el historial.' using errcode='23505'; end if;
 insert into public.agrochemical_climate_readings(id,period,reading_date,temperature_c,humidity_percent,measured_at,notes,created_by,responsible_name)
 values(p_id,p_period,day,p_temperature_c,p_humidity_percent,p_measured_at,p_notes,auth.uid(),actor.display_name);
 return jsonb_build_object('id',p_id,'status','confirmed');
end $$;
revoke all on function public.climate_dashboard(date,date) from public,anon;
revoke all on function public.climate_web_record_reading(uuid,text,numeric,numeric,timestamptz,text) from public,anon;
grant execute on function public.climate_dashboard(date,date) to authenticated;
grant execute on function public.climate_web_record_reading(uuid,text,numeric,numeric,timestamptz,text) to authenticated;
notify pgrst,'reload schema';
commit;
